from collections import defaultdict

def fill_stripe_classes(grid, axis='diag'):
    n=len(grid); w=len(grid[0])
    def key(i,j): return i if axis=='row' else (j-i)%n
    cls=defaultdict(set)
    for i,row in enumerate(grid):
        for j,v in enumerate(row):
            if v: cls[key(i,j)].add(v)
    for p in range(1,n+1):
        groups=defaultdict(set)
        for k,vs in cls.items(): groups[k%p] |= vs
        if len(groups)==p and all(len(vs)==1 for vs in groups.values()):
            m={k: next(iter(vs)) for k,vs in groups.items()}
            return [[m[key(i,j)%p] for j in range(w)] for i in range(n)]
    return grid

